import React from 'react';
import ReactDOM from 'react-dom';
import { Table } from '@alifd/next';

const dataSource = () => {
    const result = [];
    for (let i = 0; i < 5; i++) {
        result.push({
            title: `Quotation for 1PCS Nano ${3 + i}.0 controller compatible`,
            id: 100306660940 + i,
            time: 2000 + i
        });
    }
    return result;
};

class App extends React.Component {
    render() {
        return (
            <Table dataSource={dataSource()} fixedHeader maxBodyHeight={400}>
                <Table.Column title="Id" dataIndex="id" resizable width={200} />
                <Table.Column title="Title" dataIndex="title" width={400} filters={[{ label: 'Nano 3', value: 3 }]} />
                <Table.Column title="Time" dataIndex="time" width={200} />
            </Table>
        );
    }
}

ReactDOM.render(<App />, document.getElementById('root'));
